import sys, json, random, time
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
import service
from verify_plan import verify_plan

def new():
    for m in ['service','controller','planner','schema','fcflow','wire']:
        if m in sys.modules: del sys.modules[m]
    import service as sv
    return sv.handle

OKSTAT = {'ok','error','stale','blocked','invalid','prepared','denied','replay'}
fails=[]
def bad(msg, ctx=None):
    fails.append(msg)
    print('FAIL', msg, json.dumps(ctx)[:400] if ctx is not None else '')

def rnd_id(rnd):
    return rnd.choice(['a','b','c','j1','j2','zz','B_1','x.y-z'])

def gen_load(rnd):
    n=rnd.randint(2,9)
    allp=[(u,v) for u in range(n) for v in range(u+1,n)]
    rnd.shuffle(allp)
    nl=rnd.randint(0,min(len(allp),8))
    links=[list(p)+[rnd.choice([0,1,2,5,10])] for p in allp[:nl]]
    nb=rnd.randint(0,4)
    ids=rnd.sample(['a','b','c','d','e'],nb)
    bks=[]
    for i in ids:
        s=rnd.randint(0,20); e=s+rnd.randint(1,20)
        env=[[rnd.randrange(nl),rnd.randint(1,3)] for _ in range(rnd.randint(0,2))] if nl else []
        seen=set(); env2=[]
        for l,r in env:
            if l not in seen: seen.add(l); env2.append([l,r])
        bks.append({'id':i,'owner':rnd.choice(['o','p']),'window':[s,e],'envelope':env2})
    return {'op':'load','n':n,'links':links,'bookings':bks}, n, links, bks

def gen_cmd(rnd, state):
    n, links, ids = state['n'], state['links'], state['ids']
    R, T = state['R'], state['T']
    c=rnd.random()
    rev = R if rnd.random()<0.8 else max(0,R+rnd.choice([-1,1,2]))
    if c<0.10: return {'op':'about'}
    if c<0.16: return {'op':'audit','at':[rnd.randint(0,40) for _ in range(rnd.randint(0,8))]}
    if c<0.26: return {'op':'advance','time':rnd.randint(0,40)}
    if c<0.36:
        ch=[[l,rnd.randint(0,12)] for l in rnd.sample(range(len(links)+2),min(len(links)+2,rnd.randint(0,3)))]
        seen=set(); ch2=[]
        for l,cc in ch:
            if l not in seen: seen.add(l); ch2.append([l,cc])
        return {'op':'edit','rev':rev,'changes':ch2,'force':rnd.random()<0.5}
    if c<0.62:
        np_=rnd.randint(2,min(5,max(2,n)))
        parts=rnd.sample(range(min(n,48)),np_)
        rd=[[v,rnd.choice([0,1,2,3,5])] for v in parts]
        if sum(x[1] for x in rd)==0: rd[0][1]=1
        env=[[l,rnd.randint(1,4)] for l in rnd.sample(range(min(len(links),6)+1),min(rnd.randint(0,4),min(len(links),6)+1))] if links else []
        seen=set(); env2=[]
        for l,r in env:
            if l not in seen and l<len(links): seen.add(l); env2.append([l,r])
        s=rnd.randint(max(0,T-2),T+10); e=s+rnd.randint(1,20)
        per=rnd.choice([1,1,2,3,5])
        return {'op':'prepare','id':rnd_id(rnd),'owner':rnd.choice(['o','p','q']),
                'window':[s,e],'period':per,'participants':rd,'envelope':env2,'rev':rev}
    if c<0.85:
        return {'op':'commit','id':rnd_id(rnd),'owner':rnd.choice(['o','p','q']),'rev':rev}
    return {'op':'cancel','id':rnd_id(rnd),'owner':rnd.choice(['o','p','q']),'rev':rev}

def mutate(rnd, cmd):
    """produce an invalid variant"""
    s=json.dumps(cmd)
    k=rnd.randint(0,7)
    if k==0: return '{broken'
    if k==1: return ''
    if k==2: return s.replace('"op"','"op2"')
    if k==3: return s.replace(': ',': ')[:-1]
    if k==4:
        d=json.loads(s); d['extra']=1; return json.dumps(d)
    if k==5:
        d=json.loads(s); d['op']='nope'; return json.dumps(d)
    if k==6:
        return s.replace('"rev":','"rev":1.') if '"rev":' in s else s+' '
    return '\ufeff'+s

def check_denied(d, cmd, links, caps, bookings):
    if d['kind']=='capacity':
        if set(d.keys())!={'status','id','rev','kind','link','time','used','capacity'}: bad('capacity fields',d)
        l=d['link']; t=d['time']; s,e=cmd['window']
        if not (s<=t<e): bad('capacity time',d)
        if l<0 or l>=len(links): bad('capacity link',d)
        if not d['used']>d['capacity']: bad('capacity witness',d)
        if d['capacity']!=caps[l]: bad('capacity value',(d,caps))
    else:
        if set(d.keys())!={'status','id','rev','kind','cut'}: bad('cut fields',d)
        S=d['cut']
        if len(set(S))!=len(S): bad('cut dupes',d)
        parts={p[0]:p[1] for p in cmd['participants']}
        inter=[v for v in S if v in parts]
        if not inter or len(inter)==len(parts): bad('cut participation',(d,parts))
        per=cmd['period']; env={l:r for l,r in cmd['envelope']}
        tot=0
        Sset=set(S)
        for lid,(u,v) in enumerate(links):
            if (u in Sset)!=(v in Sset): tot+=per*env.get(lid,0)
        dem=sum(parts[v] for v in inter)
        if not tot<dem: bad('cut witness',(d,tot,dem))

def run_trace(seed, ncmd=60):
    rnd=random.Random(seed)
    h=new()
    state={'R':0,'T':0,'loaded':False,'n':0,'links':[],'ids':set(),'caps':[]}
    for i in range(ncmd):
        if not state['loaded']:
            cmd,n,links,bks=gen_load(rnd)
            txt=json.dumps(cmd)
            out=h(json.loads(txt))
            if out=={'status':'ok','rev':0,'now':0}:
                state['loaded']=True; state['n']=n; state['links']=[(l[0],l[1]) for l in links]
                state['caps']=[l[2] for l in links]
                state['ids']={b['id'] for b in bks}
            elif out!={'status':'invalid'}:
                bad('load reply',out)
            continue
        if rnd.random()<0.15:
            cmd=gen_cmd(rnd,state)
            txt=mutate(rnd,cmd)
            R=state['R']
            out=h(txt if txt.strip() else json.loads('{}') if False else _raw(h,txt))
            if out!={'status':'invalid'}: bad('mutant not invalid',(txt,out))
            if state['R']!=R: bad('mutant changed rev',(txt,out))
            continue
        cmd=gen_cmd(rnd,state)
        R,T=state['R'],state['T']
        out=h(cmd)
        if not isinstance(out,dict) or out.get('status') not in OKSTAT: bad('shape',out)
        op=cmd['op']
        # revision bookkeeping
        if out.get('status')=='ok' and op in ('advance','edit','commit','cancel'):
            if out['rev']!=R+1: bad('rev increment',(op,out,R))
            state['R']=out['rev']
            if op=='advance': state['T']=cmd['time']
        elif op=='cancel' and out.get('status')=='ok':
            pass
        else:
            if out.get('rev',R)!=R and out.get('status')!='ok': bad('rev preserved',(op,out,R))
        if op=='audit' and out.get('status')=='ok':
            if out['now']!=state['T']: bad('audit now',(out,state['T']))
            for t,arr in out['samples']:
                for l,a in enumerate(arr):
                    if a<0: bad('negative availability',(t,l,a))
                if len(arr)!=len(state['links']): bad('sample width')
        if op=='prepare':
            if out.get('status')=='prepared':
                parts={p[0]:p[1] for p in cmd['participants']}
                env={l:r for l,r in cmd['envelope']}
                errs=[]
                ok=verify_plan(out['plan'],state['links'],[cmd['period']*env.get(l,0) for l in range(len(state['links']))],
                               cmd['period'],env,list(parts),parts,err=lambda m:errs.append(m))
                if not ok: bad('plan invalid',(errs[:2],cmd,out['plan']['trees'][:2]))
            elif out.get('status')=='denied':
                check_denied(out,cmd,state['links'],state['caps'],None)
        if out.get('status')=='blocked':
            if set(out.keys())!={'status','rev','link','time','used','capacity'}: bad('blocked fields',out)
            if not out['used']>out['capacity']: bad('blocked witness',out)
            if out['rev']!=R: bad('blocked rev',out)
    return True

def _raw(h, txt):
    # feed raw text through the wire decoder path
    import wire
    try:
        return h(wire.decode(txt))
    except Exception:
        return {'status':'invalid'}

bad_count=0
t0=time.time()
N=int(sys.argv[1]) if len(sys.argv)>1 else 60
for seed in range(N):
    try:
        run_trace(seed)
    except Exception as e:
        import traceback; traceback.print_exc()
        bad_count+=1
        if bad_count>3: break
print('trace fails',len(fails),'exceptions',bad_count,'time %.1f'%(time.time()-t0))
